<section class="section-wrap dashboard-page admin-page"><div class="dashboard-heading"><div><p class="eyebrow">YOUR STORE AT A GLANCE</p><h1>Good morning,<br><em>let’s make it a good one.</em></h1></div><a class="button button-dark" href="<?= $e($base) ?>/admin/product">Add a product <span>＋</span></a></div><div class="stat-grid"><article class="stat-card stat-primary"><span>Gross sales</span><strong><?= number_format((float) $stats['sales'], 2) ?><small> JOD</small></strong><p>Across <?= (int) $stats['orders'] ?> orders</p><i>✳</i></article><article class="stat-card"><span>Live products</span><strong><?= (int) $stats['products'] ?></strong><p><?= (int) $stats['low_stock'] ?> running low</p><i>◌</i></article><article class="stat-card"><span>Customers</span><strong><?= (int) $stats['customers'] ?></strong><p>Growing, one ritual at a time</p><i>♡</i></article><article class="stat-card"><span>Needs a look</span><strong><?= (int) $stats['pending'] ?></strong><p>Orders to process</p><i>↗</i></article></div><div class="admin-panels"><section class="data-card"><div class="card-heading"><div><p class="eyebrow">RECENT ACTIVITY</p><h2>Latest orders</h2></div><a class="text-link" href="<?= $e($base) ?>/admin/orders">All orders ↗</a></div><div class="table-head order-admin-head"><span>Order</span><span>Customer</span><span>Status</span><span>Total</span></div><?php foreach ($recentOrders as $order): ?><a href="<?= $e($base) ?>/admin/orders" class="table-row order-admin-head"><b>#<?= (int) $order['id'] ?></b><span><?= $e($order['customer_name']) ?></span><span><i class="status-pill status-<?= $e($order['status']) ?>"><?= $e(ucfirst($order['status'])) ?></i></span><b><?= number_format((float) $order['total'], 2) ?> JOD</b></a><?php endforeach; ?><?php if (!$recentOrders): ?><p class="empty-inline">No orders yet. Your first one will show up here.</p><?php endif; ?></section><section class="data-card stock-panel"><div class="card-heading"><div><p class="eyebrow">KEEP AN EYE ON</p><h2>Low in stock</h2></div><span class="stock-icon">◌</span></div><?php foreach ($lowStock as $product): ?><div class="stock-row"><span><?= $e($product['name']) ?></span><b><?= (int) $product['stock'] ?> left</b></div><?php endforeach; ?><?php if (!$lowStock): ?><p class="empty-inline">Everything is comfortably stocked.</p><?php endif; ?><a class="text-link" href="<?= $e($base) ?>/admin/products">Manage products ↗</a></section></div></section>
